lyrics:
Manuel Naula Y. (COFRE No 14)

// Mana caspihuan,
mana azilhuan
Diospaj Espirituhuanmi. //

/// Uyajcunaca quishpiringa ///
Diospaj Espirituhuan.

// Mana caspihuan
mana azilhuan
Diospaj Espirituhuanmi. //

// Urcucunapish cuyuringa, //
Diospaj Espirituhuan.

Manuel Naula S. (MÚSICA MEXICANA)

// Huañushca q´uipa imashi tucungui,
Ñataj llaquipi chingaringuiman. //

CORO
// Jesús quishpichijpi cushicunguimi,
Sumaj llajtapi causagringuimi. //

// Cunan punllapi Jesús shamujpica,
¿Ima nishpashi ricurigringui?. //

// Canta c´ uyashpa Jesús, cayacunmi,
¿Ima nishpataj mana uyangui?. //

// Canta c´ uyashpa Jesús huañushcami,
¿Ima nishpataj mana catingui?. //

Manuel Naula Y. (Cada paso)

// Can causacushcata
Yuyaringuiari jatun
Dios ricucun //
// Diosllata Diosllata
Diosllata mañaiai. //

// Jesús cayacunmi
quishpichisha nishpa
Paillami quishpichij //
// Shamui nin shamui nin
Jesusca shamui nicun. //

// Dios c´uyashcataca
yuyarishunchijri,
Cristota cachashca. //
// Jesusca cruzpimi
Canmantaca huañushca //

// Jesús cayashcata can
uyacushpaca ama uniyangui. //
// Utca cri, utca cri, Apunchij
Jesusta cri. //

Manuel Naula Y. (Prados)

// Ñaupa ñuca causaipi llaqui Causacujpi,
Jatun c´uyaj Diosca shamuri nishpa cayarca. //

CORO
// Jatun c´uyaj Diosca shungupi rimarca.
Pai rimashcata uyashcanimi. //

// Jatunta c´uyaj Diosca canta cayacunmi,
Pai cayashcataca ama mana uyaichu. //

// Can mana uyashpaca ucu pachapimi,
huiñaita rupangui chaimanta huillacuni. //

Trad. Manuel Naula S.

// Sumaj c´uyaita Yuyarishunchij //
// Diciembre quilla Chayamunmi
Cushicushunchij. //

// Quishpichingapaj pai shamushcami //
// Apunchij Jesús shamushcami,
cushicushunchij. //

// Ñuca causaita canman cunimi //
// Canta c´uyanimi Jesuslla
Sumaj quishpichij. //

Trad. Manuel Naula S.

// Sumaj Jesucristo ima nishpachari,
Juchayujcunata c´uyashcanguica //
canca c´uyashpami sumaj llajtamanta,
ñucanchij llajtaman cachahuashcangui.
// Caipica huasipish mana tiyashcachu,
shuj corral – llapimi huacharishcangui. //

// Sumaj Jesucristo ima nishpachari
Juchayujcunata c´uyashcanguica //
jahua pachamanta sumaj angelcuna,
Jesús ñami shamun nishpa huillashca.
//// Tucuicunallataj cushicushunchijri,
Diosta pagui nishun Quishpichijmanta ////

M.S.

// Llaquij Dioslla shuyacunchij,
amopajta shuyaj shina. //
// Uyai ñucanchij mañashcata,
ñucanchijta c´uyanguimi. //

// Llaquij Dioslla c´uyaj Dioslla,
mañana yuyaita cuiri. //
// Mañashpapish mana japishpa
achcacunami causanchij. //

// Aicha munai muspachijpi,
llaquihuan huañucunchijmi. //
// Punllantamari mañacushun,
llaquij Dioslla c´uyaj Dioslla. //

Trad. Mariano Guamán Y. - Manuel Naula Y.

// Crijcunaca shamuichigri
Jatun Diosta alabashun. //
// Paillamari quishpichijca,
Chaimantami cantacuni. //

// Cullqui curi mana ninchu
paica causaitamari nin. //
// Shungu p´aquirishcacuna,
jatun Diosta mañashunchij. //

// Crijcunaca allichishun,
Cristo ñallami shamunga. //
// Paita crijcunatamari,
Pai ñalla pushaj shamunga. //

// Huiñaitami cushicushun,
Diospaj shimi chashnami nin. //
// Huaranga huatapajmari,
Jesushuan tigramushunchij. //

Trad. MFN - José Juan Naula Y.

// Manaraj mandashcatami
Cancunataca mandani. //
// Ima shina c´uyarcani,
ima shina c´uyarcani,
caishuj chaishuj c´uyanguichij. //

// Tucui shunguhuan C´uyashun,
ama jahua shimillahuan. //
// Jesucristo shamunapaj,
Jesucristo shamunapaj,
Tucuicuna allí cashun. //

// P´iñanacushca cashpapish,
Allí tucunami canchij. //
// Taita Diosta mañangapaj,
Taita Diosta mañangapaj,
Allí tucunami canchij. //

Manuel Naula Y.

// Jatun Mandaj Jesús ñamari shamunga,
Apunchij Jesusca ñamari shamunga. //
// Angelcunahuanmi paica shamusha nin,
corneta tocashca uyaringamari. //

// Pai shamunataca shuj yuyachi – nahuan,
Apunchij Jesusca cashnami parlashca. //
// Higo yurapica p´anga jundarijpi,
usia punllacuna chayamun nishcami. //

// Jesús shamunaca Noé causai punlla.
shinamari canga nishcami Jesusca. //
// Angel rimashcapish corneta tocashca. //
Ñapish uyarijpi rinallachu cangui. //

Trad. NGY

// Ñuca Jesusca ñalla shamunga,
crijcunataca pushangami. //

CORO
// Pai shamujpica tucui crijcuna,
huiñaitamari causagrishun. //

// Cambaj causaita Jesucristoman,
causacushparaj crishpa cuiri. //

// Huiñai causaipaj libropi tucui,
quillcashcacuna paihuan rishun. //

// Huañushca q´uipa cambaj almaca,
Maimanshi ringa yuyaringui. //

Trad. Manuel Naula Y.

// Jesucristo urcumanta shamujpica,
taucacuna Jesustaca catimushca. //
// Lepra ungui japishcami Jesustaca,
alliyachihuailla nishpa mañashcami. //

Jatun nanaihuanmari paica,
Jesustaca mañashcamari.
// Shungu p´aquirishca Jesusta mañashca,
chashna mañashpaca alliyashcatajmi. //

// Cunanpish chashnallataj mañaichijlla,
llaquij Jesús alliyachi tucunmari. //
// Chai ungushca shinallataj mañajpica,
Juchayujcunataca alliyachingami. //

AMR

// Crijcunapura cantacushunchij,
Tandanacushca cushicushunchij. //
// Rijcharishunchij Jatarishunchij,
Pullacunaca utcami ricun. //

Llujshirishunchij huillacushunchij,
caru llajtata puricuhunchij. //
// Jesús shamushpa tapungamari,
ima rurashca ricurigachu. //

// Huañuna huaicuta ricujpipish,
Jesucristoca huaquichingami. //
// Caru llajtata rijcunamanta,
Crijcunapura mañacushunchij. //

// Ishqui huaranga huatacunapish,
ñami pajtashca allichirishun. //
// P´iñanacushca cashca cashpapish,
ama chashnalla causacushunchij. //

PGT

// Maita purijpipish Jesusmi pushahuan //
// Tucui Paita crijta Jesusmi huaquichin //

CORO
// Huañuna huaicuta ñucalla ricujpi //
// c´uyaj Jesucristo Paillami pushahuan //
// Millai yuyaicuna muspachisha nijpi //
// C´ uyaj Jesucristo manataj saquinchu //

Manuel Guacho G.

// Tucui crijcuna cushi cantashun. //
// Jesús randirca Paipaj yahuarhuan./

// Tucui crijcuna Diosta mañashun //
// Tucui causaipi catirashunchij. //

// C´uyaj Jesusca ricucunmari. //
// cambaj shunguta yachacunmari. //

Manuel Guacho G.

// Tucui quipa huiñaicuna,
Diosta cazushpa causaichij. //
// Chashna cazushpa causashpa,
Diospaj Shimita huillaichij. //

// Josué 1:8,9
Chashna sumajta huillacun. //
// Chashna cazushpa Causashpa,
Diospaj shimita huillaichij. //

// Riqui imata manchanqui?,
Cambaj Diosca Canhuanmari. //
// Sinchi sinchita shayari,
Diosmi cantaca pushanga. //

José Gumán Y.

// C´ uyaj Taita Dioslla Apunchij Jesuslla,
Sumaj cushicuihuan canta alabasha. //

CORO
Ñuca shungupi jatun cushicui tiyan,
Cristo ñucapi causacushcamanta,
// Ñucata quishpichij sumaj Jesucristo,
tucui ñuca causaipi cantacushallami. //

// Filipenses 4;4 pi huillacun,
crijcuna Cristopi cushihuan cachun. //

// Crishca punllamanta cushi shungu cani,
sumaj Jesucristo cushicuita cujpi. //

José Remache M. Prel. No. 13

/// Jesusmari ///
Jesusmari ñucamanta huañushca,
// Calvariopi chacatashca
huañushcami Jesuscca //
/// Jesusmari ///
ñucamanta canmantapish huañushca.
// Juchamanta huañuimanta
Quishpichihuashcamari. //

/// Chai pachapi ///
purishcami purishcami Jesusca.
// Urcutapish pambatapish.
Yacutapish purishca //

c´yajmari allimari quishpichijca,
calvariopi ñucamanta huañujca.
// Ñahui ñahui Jesusta
ñucaca, ricushami //

Adj 1,2 No. 7

C´uyaj quishpichij cayacuni,
///Catihuai ///
Cutin cutin cayacuni,
///catihuai ///

Canmanta achca sufrircani,
cruzpi jayajta ubyarcani,
Yaya cayan paiman shamuilla,
///Catihuai. ///

Tucui juchata perdonasha,
///catihuai ///
mushuj shunguta canman cusha,
/// catihuai ///

Causaipi cambaj Dios cashami,
cieloman canta pushashami,
huañuipi cushita cushami,
///catihuai ///

Voces No. 16

///Shuj huasita charini intita yallimi ///
Ñuca Jesushuan.

CORO
///Bendito Cristo Canhuanmi tiyasha ///
Cambaj llajtapi.

///Can cieloman risha nishpa Jesuman shamui ///
Ama shuyangui.

///Can cushi causasha nishpa Jesusta cati ///
Ama manchangui.

///Juchata Jesusman huillai quishpiringuimi ///
Paimi quishpichin.

HFA No. 144

// Jesús shamuna punllata contento shuyacuni //
Pai cielomanta shamushpa ñucata pushangami,
// Pai shamungacama Paitami servisha nini. //

// Gentacuna p´iñajpipish Jesuspi confiashami //
chashnallataj Jesustapish cai mundopi p´iñarca,
Paica p´iñajpipish mana imata nircachu,
tucuita sufrirca ñucata quishpichingapaj.

// Jesucristo shamujpica ñahui ñahui ricusha //
tucui huañushca crijcuna cutin causaringami,
// ñucapish mushuj Cuerpohuan Jesusta tupasha //

Molodias No. 34

// Cushicuni ñuca shungupi,
Cristopaj cani cantacuni. //
// alabacuni quishpichijta,
cieloman rini cantacuni. //

Voces No. 41

// Dios c´uyajmi //
Biblia chashna ninmi.
// Dios c´uyajmi //
Juanmi chashna nirca.

// Dios c´uyajmi //
tucuita c´uyanmi.
// ninmi capitulo cuatro,
Versiculo ocho primera de Juan. //

Ecos No. 38 JJN,MM Sol-M-4/4

// Jesusmi ñucaman causaita cun,
chacatashcami ñucamanta huañushca //

CORO
// Jesús mushujyachijpi mushuj yuyai cani,
Paimi ñucata quishpichirca. //

// Jesuspaj c´uchuman shamuni,
ñuca achca juchayuj ñaupa causarcani //

// Jesucristo can juchayujta cunan cayan,
Pai cayashcata cazuiari. //

Manuel Naula Y. Fa-M-4/1

Jesucristo nishcanguimi ñucataca
huillachun tarpuj shina huillachunmi,
// agllashcangui //
chaimantami huillana yuyailla cani,
// yuyai cani //
chaimantami huillana yuyailla cani,
// Jesusmanta //

Pipish ñucata p´iñashp
macajpica cushicusha,
Canta macashca shinami
ñucata macahuashca,
Canmanta huillacujpica manchaita
// ama cungui //
Can huillachijpillamari Canmantaca,
// huillashalla //

Paicunapish ñuca shina,
// quishpirichun //
Can Apunchij Jesucristo,
// yuyachihuia //
Huillashcata Can mana yuyachijpica,
// Yangallami //
paicunapish quishpirichun yuyachipai,
// yuyachipai //

Adj. 3,4 No 61 Fa-M-4/4

// Cieloma risha //
can ri tucunguimi,
Jesús cayacunmi, //
// Cieloman risha //
Quishpichijhuan rishami.

Action No. 67 Do-M-4/1

Cristo causaita cun,
// ari cun //
Cristo causaita cun,
// ari //

Cristo mana faltanga,
// faltanga //
Cristo mana faltanga,
// mana //

Cristo cutin shamunga,
// shamunga //
Cristo cutin shamunga,
// ari //

Inspiration No. 1 Fa- M-4/1

Tucui allihuan yaya Dios,
c´uyashcamanta cayacun,
// Aleluya //

Pai mandaj cana ña shamun,
chaimanta Paiman cantashun,
// Aleluya //
// Cantanguichij // Aleluya

Ecos. No. 61 Mib M-4/1

// Cambaj shungupi cayacun //

CORO
Ricui amigo Jesús cayacun,
cambaj shungupi cayacun.

// Canta c´uyasha,
cambaj shungupi cayacun //

// Paimi amigo,
cambaj shungupi cayacun //

// Shunguta pascai,
Cambaj shungupi cayacun //

// Yaicuchihuailla,
cambaj shungupi cayacun //

// Paiman entregai,
Cambaj shungupi cayacun //

Prel No. Do-M-4/4

///Mundopaj man cashpa cushicuni //
Diosta alabashami,

///Jesuspaj cashami cushiyarini ///
Diosta alabashami.

Veces No. 24 Do-M-4/4

///Señor Jesusta catisha nini ///
huashaman mana tigrasha.

///Ñuca juchata saquisha nini ///
Señor Jesusta catisha.

///Señor Jesusca ayudahuanga ///
huashaman mana tigrasha.

/// Ña diablotami vinci pudini ///
Señor Jesuspaj poderhuan.

///Diospaj cielomanmi ña rigrini ///
Paihuan cushicui causasha.

///Mushuj runata Pai rurahuarca ///
Paihuan cushicui causasha.

Pablo Cajilema MÚSICA; BN Manuel Naula Y. La-Mm-2/1

// Huacaihuan shaicushcamari,
Diospaj c´uyaita japini //
// Achca llaqui japishcami,
cai llaqui pachapi cajpi. //

CORO
// Maicamachari Jesuslla,
llaquilla causacushalla,
// Canta ricusha ninimi,
Utca shamuilla Jesuslla. //
// Tucui ñuca yuyaihuanmi,
Jesusta shuyacunilla. //
// Amataj saquihuanguichu,
c´uyaj Quishpichij Jesuslla. //

MF Si –m M-4/1

// Apunchij Jesús ñalla shamunga,
tucui crijcunata pushangapaj. //
// Tucui crijcuna shuyacushunchij,
Tandanacushca mañacushunchij. //

// Angelcunandij Jesús shamushpa,
crijcunataca cayangamari. //
// Pai cayajpica tucui crijcuna,
p´uyupimari Paihuan tupashun. //

// Pai shamunaca pajtamucunmi,
tucui crijcuna allichirishun. //
// Paipaj shimita Yachacushunchij,
Caishuj chaishujman huillacushunchij //

// Ñuca Jesusca ñalla shamunga,
sumaj llajtaman pushangamari. //
// Chai llajtapica llaqui mana tiyan,
huiñai huiñaita cushicushunchij. //

Andrés Gómez T. Re m M-4/1

// Jesús huillagri nishca Pablo shinami,
tucui crijcunamanta mañaracunimi. //

// Tutapish punllapish mañacunillami,
allí yuyaicunata Jesús cuhuari nishpa. //

// C´uyaj Jesusmantami cashna mañani,
tucui crijcunamari shuj shinalla canchij. //

// tutapish punllapish Diosta mañashpaca,
tucui crijcunamanta mañashunchijri. //

// Pablo mañashca shina mañacushunchij,
allí yuyaicunata Jesús cuhuai nishpa. //

// C´uyaj Jesucristoca cashnami mandan,
caishuj chaishujhuan c´uyanacui nishpa. //

Manuel Guacho G. Re – m-4/1

// Diosca maipipish canta ricucunmi,
Diosca maipipish canta chapacunmi. //

CORO
// Paica ricucunmi tucuicunata,
Paica chapacunmi tucuicunata. //

// Urcuta rijpipish Pai ricucunmi,
yacupi cajpipish Paica chaipimi. //

// Tucui crijcunata Jesús michicun,
mana crijcunata Jesús cayacun. //

Re-m- 4/1

// Diospaj huahuacunaca,
shamuichij cushicushun. //
// Shuj yuyailla tucushpa,
jatun Diosta mañashun. //

// Chashna mañacui horas,
Jesucristo shamushpa. //
// cushicushpa pushanga,
sumaj Jahua pachaman. //

// Pai Jesús shamunata,
mana ricuchishcachu. //
// tutachari shamunga,
punllachari shamunga. //

// Shuj shuhua shamuj shina,
cungaimanta shamunga. //
// allí yuyaihuan cashun,
punllanta mañarashun. //

Manuel Fernández Me-m-2/1

// Jescristohuanmi purini,
Diospaj ñanpi Paimi pushahuan. //

CORO
// Tucui juchata saquishcani,
mushuj causaita Jesús cujpi. //

// Ñuca causaipi achijyachij,
Diospaj Samai Espiritulla. //

// Llaquipi c´uyailla causacuj,
cunan Jesuspajman shamuiri. //

// Jesuspajman can shamujpica,
tucui juchata p´ichangami. //

Manuel Fernández Re – m –4/1

// Jericó shuti puebopimari,
Zaqueo shuti runa causashca. //
// Jesús shamunmi nijta uyashpa,
Jesucristota tupanaman rij. //

// Taucacunami Jesushuan cajpi,
uchilla cashpa mana ricushca. //
// yura jahuaman huichiyashpami,
Jesucristota allí ricushca. //

// Yurapi cajta Jesús ricushpa,
Zaqueo caimán shamui nishcami. //
// chaita uyashpa cushicushpami,
paipaj huasiman pushashpa rishca, //

// Cunan punllapish Jesucristoca,
can juchayujta cayacunmari. //
// Zaqueo shina canpish shamuilla,
Jesucristoca quishpichingami. //

Manuel Fernández Re- m- 3-1

// Jesucristoca agllahuashcami,
Paipaj shimita huillachun nishpa. //
// Pai mingashcata pajtachingapaj,
caru llajtata puricunchijmi. //

// Cunanca caipi cayaca mana,
Cayapaj caya maipishi cashun. //
// Blancoman cashpa, runaman cashpa,
Diospaj shimita huillacushunchij. //

// Huañuna huaicuta ricujpipish,
Jesucristomi huaquichihuanga. //
// Paipaj shimita huillacushunchij,
caishuj chaishujman parlacushunchij. //

// Sachata cashpa, urcuta cashpa,
chirita cashpa, cunujta cashpa. //
// Llaquihuan cashpa, cushihuan cashpa,
Diospaj shimita huillacushunmi. //

Trad Manuel Fernández Re - m-4/1

// Jesucristo huañurca,
ñucata quishpichingapaj. //

CORO
// Jesusmi maillahuarca,
tucui ñuca juchata
chaimanta cushicuni,
ñuca Jesushuan. //

// Jesús ñalla shamunga,
ñucata pusharingami. //

// Jahua pachaman risha,
huiñaita cushicungapaj. //

Manuel Fernández Si-m-4/1

// Ñuca Yayaca c´uyacunmari,
Paitami cunan cushichicuni. //
// chaimantamari cantasha
nini. //

// Ñuca yayata c´uyacujtaca,
llaqui japijpi, huacai japijpi. //
// Paitaca manataj
cungashachu,
chaimanta cunan
cushicunimi. //
// Ñuca Yayahuan risha
nishpaca,
Paita catingui, Paita
chasquingui. //
// chaipica llaqui, chaipica
huacai,
illangamari cushicunami. //

// Shuj shmuj punlla Paita
catijta,
Cushicushpami Paica
chasquinga. //
// chaimanta cunan
causacushparaj,
Pai mingashcata
pajtachicushun. //

Manuel Fernández La – m-4/1

// Jahua pacha Dioslla
yachachihuaiari //
// Can causana huasi
ñucanchij cashcanchij. //

// Corintios libropi 3:16 pi //
// chashna sumajtaca
huillacushcamari //

// Jesusta crishpalla ñami
yachashcanchij //
// Dios causana huasi
ñucanchij cashcanchij. //

Si – m- 2- 1

// Alli michij cayacunmi,
llaquilla purijcunata. //
// Paipaj rimai cayashcata,
cunan uyai tucunguimi. //

// Huillashunchij Jesusmanta,
huillashunchij tucuicuna. //
// Jesucristo shamungami,
Shuhua shina cungaimanta. //

// Huiñai causaita charishca,
ricuchij coronatami. //
// C´uyaj Diosca cushalla nin,
tucui Paita crijcunaman. //

// Tucui Paita catijcuna,
shuj yuyailla catishunchij. //
// Quishpichijta yuyarishpa,
ñalla Paica shamungami. //

Manuel Chicaiza I. – Re – m -4/1

// C´uyaj Yayalla, c´uyaj Jesuslla,
Can c´uyajpimi, Can cayajpimi. //
// Can Yayallata, Can Jesusllata,
mañacunilla, cantacunilla. //

CORO
// Cunanca Yaya yachachihuailla,
Cambaj shimita huillacungapaj. //
// Maita rishpapish yachachingapaj,
alli yuyaita cuhuangui Jesús. //
// Saruncunaca c´uyaj Jesuslla,
Cambaj shimita mana yachashpa. //
// millaipajllata ruracurcanchij,
chashna cajpipish c´uyashcanguimi. //

// Cunanca Yaya ñuca yuyaita,
ñuca aichata mingarinimi. //
// Apunchij Jesús shamungacama,
ñuca causaita huaquichihuailla. //

Mi – m – 4- 1

// Ñuca Yayalla, ñuca Jesuslla,
c´uyashpallami quishpichishcangui. //
// Can shina c´uyaj mana tiyanchu,
cai pachapica p´iñancunami. //

// Apunchij Jesús huañushcamanta,
Juchayujtaca quishpichihuashca. //
// Ñuca juchata cungarishpami,
c´uyaj Yayaca allí tucushca. //

// Paipaj Churita cachashpamari,
Pai c´uyashcata ricuchihuashca. //
// Paipaj Churica tacui juchata,
quishpichingapaj cruzpi huañushca, //

// Quishpichishpapish sumaj huillaita,
Huillachunmari mingahuashca. //
// Diospaj shimita huillachunmari,
Pai shamuncama mingahuashca. //

